def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    wall = next(c for c in range(w) if all(grid[r][c] == 2 for r in range(h)))

    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, bg)]
    lo = min(c for r, c in obj)
    hi = max(c for r, c in obj)

    # Place the object adjacent to the wall, then draw an 8 stripe
    # immediately beyond its opposite edge.
    if wall < lo:
        shift = wall + 1 - lo
        stripe = hi + shift + 1
    else:
        shift = wall - 1 - hi
        stripe = lo + shift - 1

    for r, c in obj:
        out[r][c] = bg
    for r, c in obj:
        out[r][c + shift] = grid[r][c]
    if 0 <= stripe < w:
        for r in range(h):
            out[r][stripe] = 8
    return out
